// ring size N driven by density (rebuild sim only when it actually changes)
const N = 40 + Math.round((P.density < 0 ? 0 : P.density > 1 ? 1 : P.density) * 56);
const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };

function deriv(x, out, F, n) {
  for (let i = 0; i < n; i++) {
    const ip1 = x[(i + 1) % n], im2 = x[(i - 2 + n) % n], im1 = x[(i - 1 + n) % n];
