  deriv(tmp, k2, F, n);
  for (let i = 0; i < n; i++) tmp[i] = x[i] + 0.5 * dt * k2[i];
  deriv(tmp, k3, F, n);
  for (let i = 0; i < n; i++) tmp[i] = x[i] + dt * k3[i];
  deriv(tmp, k4, F, n);
