  stepRK4(x, F, n, dt, S.k1, S.k2, S.k3, S.k4, S.tmp);
  stepRK4(x, F, n, dt, S.k1, S.k2, S.k3, S.k4, S.tmp);
  let mean = 0; for (let i = 0; i < n; i++) mean += x[i]; mean /= n;
  const base = S.head * n;
  for (let i = 0; i < n; i++) S.hist[base + i] = x[i] - mean; // store anomaly
