}

// ---- (re)build simulation: new size / seed / ring-size ----
if (S.needSim || S.seedUsed !== P.seed || S.n !== N) {
  S.seedUsed = P.seed; S.n = N; S.needSim = false;
  S.x = new Float64Array(N); S.k1 = new Float64Array(N); S.k2 = new Float64Array(N);
  S.k3 = new Float64Array(N); S.k4 = new Float64Array(N); S.tmp = new Float64Array(N);
  S.hist = new Float32Array(BW * N); S.head = 0; S.acc = 0; S.lastT = null;
