  const Fb = P.force;
  for (let i = 0; i < N; i++) S.x[i] = Fb + (fr(i + 11) - 0.5) * 0.8;
  S.x[(N / 2) | 0] += 1.0; // symmetry-breaking kick
  for (let c = 0; c < BW; c++) pushColumn(Fb); // warm the whole history so frame-1 is full
}

// ---- forcing F drifts with section: ordered waves <-> full chaos ----
const secF = 3.0 * Math.sin(K.section * 0.7 + 0.6) + 1.6 * Math.sin(K.section * 1.9 + 2.0);
const Flive = Math.max(2.6, Math.min(18, P.force + secF + K.intensity * 1.4 + A.bass * 3.0));

// ---- advance scroll from continuous K.t (never re-phases) ----
if (S.lastT == null || K.t < S.lastT) S.lastT = K.t;
const colsPerT = 58 * (0.4 + P.speed * 0.8);
S.acc += Math.max(0, K.t - S.lastT) * colsPerT; S.lastT = K.t;
let toPush = Math.floor(S.acc); if (toPush > 6) toPush = 6; S.acc -= toPush;
for (let p = 0; p < toPush; p++) pushColumn(Flive);

// ---- palette / colormap setup (per-frame, cheap) ----
function hsb2rgb(h, s, v) {
