const hb = (P.hue + S.hoff * 36 + K.section * 16) % 360;
const cold = hsb2rgb(hb, 0.78, 0.60), warm = hsb2rgb((hb + 152) % 360, 0.80, 0.58), mid = [0.84, 0.84, 0.79];
const inferno = [[0.02,0.01,0.07],[0.30,0.05,0.42],[0.68,0.12,0.32],[0.92,0.42,0.10],[0.99,0.85,0.30],[1.0,0.98,0.90]];
