const ice     = [[0.02,0.04,0.13],[0.03,0.20,0.40],[0.08,0.45,0.62],[0.28,0.72,0.82],[0.72,0.94,1.0],[0.95,0.99,1.0]];
function ramp(st, t) { t = t < 0 ? 0 : t > 1 ? 1 : t; const n = st.length - 1, f = t * n; let i = Math.floor(f); if (i >= n) i = n - 1; const g = f - i, a = st[i], b = st[i + 1]; return [a[0] + (b[0] - a[0]) * g, a[1] + (b[1] - a[1]) * g, a[2] + (b[2] - a[2]) * g]; }
