const style = P.style;
function col(anom) {
  const a = Math.tanh(anom * k); // -1..1
  if (style === 'thermal') return ramp(inferno, (a + 1) * 0.5);
  if (style === 'viridis') return ramp(viridis, (a + 1) * 0.5);
  if (style === 'ice') return ramp(ice, (a + 1) * 0.5);
  if (style === 'mono') { const t = Math.pow((a + 1) * 0.5, 0.85); return [t * 0.98, t * 0.99, t]; }
