  if (a < 0) { const t = -a; return [mid[0] + (cold[0] - mid[0]) * t, mid[1] + (cold[1] - mid[1]) * t, mid[2] + (cold[2] - mid[2]) * t]; }
  const t = a; return [mid[0] + (warm[0] - mid[0]) * t, mid[1] + (warm[1] - mid[1]) * t, mid[2] + (warm[2] - mid[2]) * t];
}

// ---- render Hovmoller from history ----
const g = S.g; g.loadPixels(); const px = g.pixels;
const n = S.n, hist = S.hist, head = S.head;
const sitesShown = n / (P.scale < 0.5 ? 0.5 : P.scale);
const y0 = P.y * n;
const shear = (P.x - 0.5) * sitesShown * 0.6;
const expo = 0.84 + P.energy * 0.20 + K.swell * 0.10 * P.energy;
