  const hc = (head + xp) % BW, base = hc * n;
  const sh = y0 + shear * (xp / BW - 0.5);
  for (let yp = 0; yp < BH; yp++) {
    let sp = sh + (yp / BH) * sitesShown;
    let i0 = Math.floor(sp); const f = sp - i0; i0 = ((i0 % n) + n) % n; const i1 = (i0 + 1) % n;
