    const c = col(anom);
    const o = 4 * (yp * BW + xp);
    px[o] = Math.max(0, Math.min(255, c[0] * expo * 255));
    px[o + 1] = Math.max(0, Math.min(255, c[1] * expo * 255));
    px[o + 2] = Math.max(0, Math.min(255, c[2] * expo * 255));
    px[o + 3] = 255;
  }
