push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();

// ---- audio shimmer ON TOP of the clk baseline (partial, never full-frame flash) ----
if (P.energy > 0.02 && (A.treble > 0.02 || A.rms > 0.02)) {
  push(); blendMode(ADD); noStroke();
  const glow = (A.treble * 0.5 + A.rms * 0.35) * P.energy;
  fill((hb + 30) % 360, 24, 100, glow * 20);
  rect(0, 0, width, height);
  blendMode(BLEND); pop();
}
